import{_ as t,o as a,c as n,a0 as r}from"./chunks/framework.jwovEGr5.js";const h=JSON.parse('{"title":"Crate: frensense-runtime - Dynamic Runtime Instrumentation","description":"","frontmatter":{},"headers":[],"relativePath":"frensense-paper/07_CRATE_RUNTIME.md","filePath":"frensense-paper/07_CRATE_RUNTIME.md"}'),s={name:"frensense-paper/07_CRATE_RUNTIME.md"};function o(i,e,c,d,l,p){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="crate-frensense-runtime-dynamic-runtime-instrumentation" tabindex="-1">Crate: <code>frensense-runtime</code> - Dynamic Runtime Instrumentation <a class="header-anchor" href="#crate-frensense-runtime-dynamic-runtime-instrumentation" aria-label="Permalink to &quot;Crate: `frensense-runtime` - Dynamic Runtime Instrumentation&quot;">​</a></h1><p><strong>Path:</strong> <code>frensense-runtime/src/</code><br><strong>Role:</strong> Standalone sidecar process. Instruments a running application to confirm or refute static findings dynamically.</p><hr><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Static analysis can only tell you that tainted data <em>could</em> reach a sink - it cannot tell you that it <em>does</em> reach a sink with a real HTTP request. The runtime crate bridges this gap: it runs alongside the target application, observes actual executions, and correlates them with static findings.</p><p>This is the Frensense answer to the broader question: &quot;Is this a real vulnerability or a false positive in my deployment?&quot;</p><hr><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Static Analysis Engine                 Runtime Sidecar</span></span>\n<span class="line"><span>        │                                     │</span></span>\n<span class="line"><span>        │  findings.json                      │</span></span>\n<span class="line"><span>        └───────────────────────────────────► │</span></span>\n<span class="line"><span>                                              │</span></span>\n<span class="line"><span>                    Target Application        │</span></span>\n<span class="line"><span>                    (Express / Hono / Axum)   │</span></span>\n<span class="line"><span>                           │                  │</span></span>\n<span class="line"><span>                           │  HTTP traffic    │</span></span>\n<span class="line"><span>                           ◄──────────────────┤  route_extractor.rs</span></span>\n<span class="line"><span>                           │                  │</span></span>\n<span class="line"><span>                           │  trace events    │</span></span>\n<span class="line"><span>                           └─────────────────►│  tracer.rs</span></span>\n<span class="line"><span>                                              │</span></span>\n<span class="line"><span>                                         scheduler.rs</span></span>\n<span class="line"><span>                                              │</span></span>\n<span class="line"><span>                                         oracle.rs</span></span>\n<span class="line"><span>                                              │</span></span>\n<span class="line"><span>                                         canary.rs</span></span>\n<span class="line"><span>                                              │</span></span>\n<span class="line"><span>                                      advisory.rs → output</span></span></code></pre></div><hr><h2 id="module-reference" tabindex="-1">Module Reference <a class="header-anchor" href="#module-reference" aria-label="Permalink to &quot;Module Reference&quot;">​</a></h2><h3 id="main-rs-sidecar-entry-point" tabindex="-1"><code>main.rs</code> - Sidecar Entry Point <a class="header-anchor" href="#main-rs-sidecar-entry-point" aria-label="Permalink to &quot;`main.rs` - Sidecar Entry Point&quot;">​</a></h3><p>Starts the runtime sidecar as a separate process. Accepts configuration via <code>config.rs</code> (port, target URL, probe intervals, finding file path).</p><h3 id="session-rs-session-management" tabindex="-1"><code>session.rs</code> - Session Management <a class="header-anchor" href="#session-rs-session-management" aria-label="Permalink to &quot;`session.rs` - Session Management&quot;">​</a></h3><p>Manages the analysis session lifecycle:</p><ul><li><code>Session::new()</code> - initialize a runtime analysis session.</li><li><code>Session::attach(target_url)</code> - connect to the running target application.</li><li><code>Session::run()</code> - main event loop: collect traces, schedule probes, report findings.</li><li><code>Session::detach()</code> - clean shutdown without disrupting the target.</li></ul><h3 id="route-extractor-rs-http-route-map-extraction" tabindex="-1"><code>route_extractor.rs</code> - HTTP Route Map Extraction <a class="header-anchor" href="#route-extractor-rs-http-route-map-extraction" aria-label="Permalink to &quot;`route_extractor.rs` - HTTP Route Map Extraction&quot;">​</a></h3><p>Queries the running target to extract its route map. Supports:</p><ul><li><strong>Express.js:</strong> Queries the <code>app._router.stack</code> internal structure via a debug endpoint.</li><li><strong>Fastify:</strong> Uses <code>fastify.printRoutes()</code> output.</li><li><strong>Hono:</strong> Route inspection via the framework&#39;s internal route registry.</li><li><strong>Axum:</strong> Route enumeration via the <code>axum::Router</code> debug format.</li></ul><p>The extracted route map (<code>HashMap&lt;Method, Vec&lt;PathPattern&gt;&gt;</code>) is used to generate targeted probe requests.</p><h3 id="tracer-rs-execution-trace-collection" tabindex="-1"><code>tracer.rs</code> - Execution Trace Collection <a class="header-anchor" href="#tracer-rs-execution-trace-collection" aria-label="Permalink to &quot;`tracer.rs` - Execution Trace Collection&quot;">​</a></h3><p>Collects execution traces from the target:</p><ul><li><strong>Node.js:</strong> Uses <code>--inspect</code> protocol (V8 debugger) to capture function call stacks.</li><li><strong>Rust/Axum:</strong> Uses tracing hooks via <code>tracing-subscriber</code> integration.</li><li>Traces are recorded as <code>TraceEvent { function_name, args_snapshot, timestamp }</code> sequences.</li></ul><h3 id="scheduler-rs-probe-scheduling" tabindex="-1"><code>scheduler.rs</code> - Probe Scheduling <a class="header-anchor" href="#scheduler-rs-probe-scheduling" aria-label="Permalink to &quot;`scheduler.rs` - Probe Scheduling&quot;">​</a></h3><p>Schedules when and how often probes are sent:</p><ul><li><code>LinearScheduler</code> - sends probes at fixed intervals.</li><li><code>AdaptiveScheduler</code> - increases probe frequency for findings with high static confidence.</li><li><code>BurstScheduler</code> - sends a burst of probes to test rate limiting.</li></ul><h3 id="oracle-rs-ground-truth-oracle" tabindex="-1"><code>oracle.rs</code> - Ground-Truth Oracle <a class="header-anchor" href="#oracle-rs-ground-truth-oracle" aria-label="Permalink to &quot;`oracle.rs` - Ground-Truth Oracle&quot;">​</a></h3><p>After sending a probe, the oracle determines whether the vulnerability was triggered:</p><ul><li>Checks HTTP response codes and bodies for error signatures.</li><li>Inspects trace events for sink function invocations with tainted arguments.</li><li>Compares expected vs. actual behavior from <code>[frensense]</code> block&#39;s <code>exploit_scenario</code> field.</li></ul><h3 id="canary-rs-canary-payload-injection" tabindex="-1"><code>canary.rs</code> - Canary Payload Injection <a class="header-anchor" href="#canary-rs-canary-payload-injection" aria-label="Permalink to &quot;`canary.rs` - Canary Payload Injection&quot;">​</a></h3><p>For each finding marked with <code>runtime_probe</code>, generates a canary payload:</p><ul><li><strong>SSRF:</strong> Sends a request URL pointing to a controlled canary server; checks if the server receives an outbound request.</li><li><strong>SQLi:</strong> Sends time-based blind payloads; measures response latency.</li><li><strong>CMDI:</strong> Sends payloads that write to a canary file; checks if file exists.</li><li><strong>Open Redirect:</strong> Sends a redirect to a controlled URL; follows redirects.</li></ul><h3 id="advisory-rs-runtime-finding-formatter" tabindex="-1"><code>advisory.rs</code> - Runtime Finding Formatter <a class="header-anchor" href="#advisory-rs-runtime-finding-formatter" aria-label="Permalink to &quot;`advisory.rs` - Runtime Finding Formatter&quot;">​</a></h3><p>Converts confirmed runtime findings into <code>Advisory</code> structs with <code>confidence = 0.99</code> (confirmed by dynamic execution). These are emitted alongside static findings in the final report.</p><h3 id="probes-probe-definitions" tabindex="-1"><code>probes/</code> - Probe Definitions <a class="header-anchor" href="#probes-probe-definitions" aria-label="Permalink to &quot;`probes/` - Probe Definitions&quot;">​</a></h3><p>Individual probe implementations for each vulnerability class:</p><table tabindex="0"><thead><tr><th>Probe</th><th>Technique</th></tr></thead><tbody><tr><td><code>ssrf_probe</code></td><td>DNS/HTTP canary server callback</td></tr><tr><td><code>sqli_probe</code></td><td>Time-based blind, error-based, UNION-based</td></tr><tr><td><code>cmdi_probe</code></td><td><code>sleep</code>/<code>ping</code> timing, file write canary</td></tr><tr><td><code>path_traversal_probe</code></td><td><code>/etc/passwd</code> content detection</td></tr><tr><td><code>open_redirect_probe</code></td><td>Redirect chain following</td></tr><tr><td><code>xss_probe</code></td><td>Reflected payload detection in response</td></tr></tbody></table><h3 id="adapters-language-runtime-adapters" tabindex="-1"><code>adapters/</code> - Language Runtime Adapters <a class="header-anchor" href="#adapters-language-runtime-adapters" aria-label="Permalink to &quot;`adapters/` - Language Runtime Adapters&quot;">​</a></h3><p>Language-specific hooks for attaching to running processes:</p><table tabindex="0"><thead><tr><th>Adapter</th><th>Mechanism</th></tr></thead><tbody><tr><td><code>node_adapter</code></td><td>V8 Inspector Protocol, <code>--require</code> hooks</td></tr><tr><td><code>rust_adapter</code></td><td><code>tracing</code> crate subscriber, <code>tokio-console</code> protocol</td></tr><tr><td><code>go_adapter</code></td><td><code>pprof</code> endpoint, Go runtime trace</td></tr></tbody></table><hr><h2 id="cs-theory" tabindex="-1">CS Theory <a class="header-anchor" href="#cs-theory" aria-label="Permalink to &quot;CS Theory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>Application</th></tr></thead><tbody><tr><td><strong>Dynamic analysis</strong></td><td>Runtime observation of actual program execution</td></tr><tr><td><strong>Concolic testing</strong></td><td>Concrete execution + symbolic canary payloads to test reachability</td></tr><tr><td><strong>Runtime verification</strong></td><td>Check properties (no tainted data reaches sink) against actual execution</td></tr><tr><td><strong>Fuzzing probes</strong></td><td>Targeted input generation to trigger specific vulnerability classes</td></tr><tr><td><strong>Fault injection</strong></td><td>Canary payloads as fault-injection to confirm exploitability</td></tr></tbody></table><hr><h2 id="relationship-to-static-analysis" tabindex="-1">Relationship to Static Analysis <a class="header-anchor" href="#relationship-to-static-analysis" aria-label="Permalink to &quot;Relationship to Static Analysis&quot;">​</a></h2><p>The runtime crate does NOT replace static analysis - it complements it:</p><ul><li>Static analysis has <strong>high recall</strong> (finds all potential paths) but moderate precision.</li><li>Runtime probing has <strong>perfect precision</strong> for confirmed findings (if the probe triggers, it&#39;s real) but zero recall for unexplored paths.</li></ul><p>Together they form a <strong>confidence escalation pipeline</strong>: static analysis identifies candidates, runtime probing confirms the highest-confidence ones.</p>',48)])])}const g=t(s,[["render",o]]);export{h as __pageData,g as default};
